body.raw:
{
  "filePath": "uploads/your-file.txt",
  "chunkSize": 1000,
  "chunkOverlap": 200,
  "metadata": {
    "category": "documentation",
    "source": "test"
  }
}

{
  "documents": [
    {
      "content": "LangChain est un framework pour développer des applications alimentées par des modèles de langage.",
      "metadata": {
        "source": "documentation",
        "category": "intro"
      }
    },
    {
      "content": "Redis est une base de données en mémoire utilisée pour le cache.",
      "metadata": {
        "source": "documentation",
        "category": "database"
      }
    }
  ]
}

{
  "query": "Qu'est-ce que LangChain ?",
  "k": 5,
  "includeScores": true
}

{
  "content": "Contenu mis à jour sur LangChain et ses fonctionnalités avancées.",
  "metadata": {
    "source": "documentation",
    "updated": true
  }
}

{
  "query": "Redis cache integration best practices"
}

{
  "query": "What are the detailed implementation strategies for distributed caching systems using Redis Cluster with automatic failover and master-slave replication patterns?"
}

{
  "filePath": "uploads/your-file.txt",
  "chunkSize": 1000,
  "chunkOverlap": 200,
  "metadata": {
    "source": "documentation",
    "category": "technical"
  }
}

{
  "prompt": "Explique ce qu'est Redis en 2 phrases.",
  "temperature": 0.7,
  "maxTokens": 200
}

{
  "messages": [
    {
      "role": "system",
      "content": "Tu es un assistant technique expert en NestJS."
    },
    {
      "role": "user",
      "content": "Comment intégrer Redis dans NestJS ?"
    }
  ],
  "temperature": 0.8,
  "maxTokens": 500
}

{
  "provider": "openai"
}

{
  "type": "rag",
  "includeFewShot": false,
  "variables": {
    "context": "LangChain est un framework pour développer des applications alimentées par des modèles de langage.",
    "question": "Qu'est-ce que LangChain ?"
  }
}

{
  "type": "conversation",
  "includeHistory": true,
  "variables": {
    "message": "Bonjour, comment ça va ?",
    "history": "User: Salut!\nAssistant: Bonjour!"
  }
}

{
  "type": "summarization",
  "maxLength": 100,
  "variables": {
    "text": "LangChain est un framework open source qui permet de développer des applications alimentées par des modèles de langage. Il fournit des outils pour gérer les prompts, les chaînes de traitement, et l'intégration avec diverses sources de données."
  }
}

{
  "type": "code",
  "variables": {
    "code": "const sum = (a, b) => a + b;",
    "language": "JavaScript"
  }
}

{
  "type": "extraction",
  "variables": {
    "text": "John Doe, 35 ans, habite à Paris. Email: john@example.com",
    "format": "JSON avec fields: name, age, city, email"
  }
}

{
  "type": "search",
  "variables": {
    "query": "LangChain embeddings",
    "sources": "documentation officielle, GitHub, Stack Overflow",
    "maxResults": "10"
  }
}

{
  "template": "Bonjour {name}, vous avez {age} ans et vous vivez à {ville}.",
  "variables": {
    "name": "Alice",
    "age": 30,
    "ville": "Paris"
  }
}

{
  "template": "Question: {question}\nContext: {context}",
  "requiredVariables": ["question", "context"]
}

{
  "template": "Analyse {topic} en utilisant {method} et génère un rapport."
}

{
  "name": "search",
  "content": "Rechercher des informations sur {query} en utilisant les sources suivantes: {sources}. Limiter à {maxResults} résultats pertinents.",
  "description": "Template pour effectuer des recherches ciblées",
  "variables": ["query", "sources", "maxResults"]
}

{
  "name": "scraper",
  "content": "Extraire les données suivantes d'une page web {url}: {fields}. Format de sortie: {format}. Ignorer les éléments: {excludeSelectors}.",
  "description": "Template pour extraire des données de pages web",
  "variables": ["url", "fields", "format", "excludeSelectors"]
}

{
  "name": "translator",
  "content": "Traduire le texte suivant de {sourceLang} vers {targetLang}:\n\nTexte: {text}\n\nFormat de sortie: {format}. Ton: {tone}.",
  "description": "Template pour traduction avec contrôle du ton",
  "variables": ["text", "sourceLang", "targetLang", "format", "tone"]
}

{
  "description": "Template mis à jour pour recherches avancées",
  "content": "Rechercher des informations détaillées sur {query} dans les sources: {sources}. Limiter à {maxResults} résultats. Filtrer par: {filters}.",
  "variables": ["query", "sources", "maxResults", "filters"]
}

{
  "category": "rag",
  "input": "Qu'est-ce que LangChain ?",
  "output": "LangChain est un framework open source pour développer des applications alimentées par des modèles de langage.",
  "context": "LangChain fournit des abstractions et des outils pour intégrer des LLMs dans des applications."
}

{
  "category": "summarization",
  "input": "L'intelligence artificielle transforme rapidement le monde du travail, créant de nouvelles opportunités tout en soulevant des questions éthiques importantes sur l'automatisation et l'emploi.",
  "output": "L'IA révolutionne l'emploi avec des opportunités et défis éthiques."
}

{
  "template": "Écris une salutation {tone} pour {recipient}.",
  "variables": {
    "tone": "professionnelle",
    "recipient": "un nouveau client"
  },
  "temperature": 0.7
}

{
  "steps": [
    {
      "name": "topic",
      "template": "Propose un sujet d'histoire sur {theme}",
      "inputVariables": ["theme"],
      "outputKey": "story_topic"
    },
    {
      "name": "plot",
      "template": "Crée une intrigue pour: {story_topic}",
      "inputVariables": ["story_topic"],
      "outputKey": "plot"
    },
    {
      "name": "story",
      "template": "Écris une courte histoire basée sur: {plot}",
      "inputVariables": ["plot"],
      "outputKey": "final_story"
    }
  ],
  "initialVariables": {
    "theme": "science-fiction"
  },
  "temperature": 0.8
}

{
  "task": "Calcule (25 * 4) + (100 / 5) et explique le résultat",
  "tools": ["calculator"],
  "maxIterations": 3,
  "verbose": true
}

{
  "name": "weather_api",
  "description": "Récupère la météo actuelle pour une ville. Input: nom de la ville",
  "endpoint": "https://api.openweathermap.org/data/2.5/weather",
  "method": "GET",
  "headers": {
    "Accept": "application/json"
  },
  "responseTemplate": "Météo à {name}: {weather[0].description}, Température: {main.temp}°C"
}
